{
  "missing_information": [
    {
      "category": "Handover Trigger",
      "gap": "No defined time or event that signals the start of the evening handover",
      "why_it_matters": "Without a clear trigger, it is impossible to determine when the process begins or how to automate initiation"
    },
    {
      "category": "Information Format",
      "gap": "It is unclear how the outgoing caregiver communicates outstanding tasks — verbally, written note, app, or other medium",
      "why_it_matters": "The communication medium determines whether structured data exists and what automation or digitization is feasible"
    },
    {
      "category": "Task Inventory",
      "gap": "The specific categories of tasks that are tracked and handed over are not described",
      "why_it_matters": "Knowing the task types (medication, meals, appointments, hygiene, etc.) is essential for modeling the process and identifying automation candidates"
    },
    {
      "category": "Next-day Preparation Steps",
      "gap": "The concrete actions involved in 'getting things ready for the next day' are not specified",
      "why_it_matters": "Without knowing these steps, it is impossible to assess their complexity, sequencing, or automation potential"
    },
    {
      "category": "Roles and Responsibilities",
      "gap": "It is unclear whether the incoming caregiver has a fixed role or whether responsibilities vary by person",
      "why_it_matters": "Role variability affects whether a standardized handover checklist or adaptive workflow is needed"
    },
    {
      "category": "Completion Verification",
      "gap": "There is no information on how either caregiver confirms that the handover and preparation are complete",
      "why_it_matters": "Without a verification or sign-off step, tasks may be missed and the process cannot be reliably closed or audited"
    }
  ],
  "clarification_questions": [
    {
      "id": "Q1",
      "question": "What specific event or time signals that the evening handover should begin — for example, a fixed clock time, the arrival of the incoming caregiver, or completion of a particular care task?",
      "targets": ["Handover Trigger"]
    },
    {
      "id": "Q2",
      "question": "How do you currently communicate the list of outstanding tasks to the incoming caregiver — for example, verbally, a written note, a shared app, or some other method?",
      "targets": ["Information Format"]
    },
    {
      "id": "Q3",
      "question": "What categories of tasks are typically included in the handover — for example, medication administration, meal preparation, medical appointments, or personal hygiene?",
      "targets": ["Task Inventory"]
    },
    {
      "id": "Q4",
      "question": "Can you walk me through the specific steps involved in preparing for the next day — for example, laying out medications, preparing food, or checking a schedule?",
      "targets": ["Next-day Preparation Steps"]
    },
    {
      "id": "Q5",
      "question": "Does the incoming caregiver always take on the same responsibilities, or do the tasks assigned during handover vary depending on who is taking over?",
      "targets": ["Roles and Responsibilities"]
    },
    {
      "id": "Q6",
      "question": "How do you and the incoming caregiver confirm that the handover is complete and nothing has been missed — is there a checklist, a verbal confirmation, or no formal sign-off?",
      "targets": ["Completion Verification"]
    }
  ]
}
